mat2 calculerMatriceRotation2D(float angle) {
    float cosinusAngle = cos(angle), sinusAngle = sin(angle);
    return mat2(cosinusAngle, -sinusAngle, sinusAngle, cosinusAngle);
}

float calculerDistanceMandelbulbAnime(vec3 positionEspace, float tempsActuel) {
    float tempsCycleLocal = mod(tempsActuel, 1.8);

    float ondeRebondissement = exp(-2.5 * tempsCycleLocal) * cos(tempsCycleLocal * 14.0);
    float etirementAxeX = 1.0 + 0.35 * ondeRebondissement;
    float etirementAxeY = 1.0 - 0.28 * ondeRebondissement;
    float etirementAxeZ = 1.0 + 0.15 * ondeRebondissement;

    vec3 positionDeformee = positionEspace;
    positionDeformee.x /= etirementAxeX;
    positionDeformee.y /= etirementAxeY;
    positionDeformee.z /= etirementAxeZ;

    float ondulationsLiquides = sin(positionDeformee.x * 3.0 + tempsActuel * 3.0) * cos(positionDeformee.y * 3.0 - tempsActuel * 2.5) * 0.04 * ondeRebondissement;

    float deriveeDistance = 1.0;
    float rayonSphere = 0.0;
    float puissanceFractale = 8.0;

    for (int etapeIteration = 0; etapeIteration < 8; etapeIteration++) {
        rayonSphere = length(positionDeformee);
        if (rayonSphere > 4.0) break;

        float angleTheta = acos(clamp(positionDeformee.z / rayonSphere, -1.0, 1.0));
        float anglePhi = atan(positionDeformee.y, positionDeformee.x);

        angleTheta += (0.05 * sin(rayonSphere * 3.0 - tempsActuel * 2.0) + ondulationsLiquides);
        anglePhi += (0.08 * cos(positionDeformee.z * 2.5 + tempsActuel * 1.8) + ondeRebondissement * 0.1);

        deriveeDistance = pow(rayonSphere, puissanceFractale - 1.0) * puissanceFractale * deriveeDistance + 1.0;

        float rayonPuissance = pow(rayonSphere, puissanceFractale);
        angleTheta *= puissanceFractale;
        anglePhi *= puissanceFractale;

        positionDeformee = rayonPuissance * vec3(sin(angleTheta) * cos(anglePhi), sin(angleTheta) * sin(anglePhi), cos(angleTheta));
        positionDeformee += positionEspace;
    }

    return 0.5 * log(max(rayonSphere, 1.0001)) * rayonSphere / max(deriveeDistance, 0.0001);
}

vec3 calculerNormaleGeometrie(vec3 positionEspace, float tempsActuel, float derniereDistance) {
    float decalageEpsilon = max(0.001, derniereDistance * 0.5);
    vec2 vecteurDecalage = vec2(decalageEpsilon, -decalageEpsilon);
    return normalize(
        vecteurDecalage.xyy * calculerDistanceMandelbulbAnime(positionEspace + vecteurDecalage.xyy, tempsActuel) +
        vecteurDecalage.yyx * calculerDistanceMandelbulbAnime(positionEspace + vecteurDecalage.yyx, tempsActuel) +
        vecteurDecalage.yxy * calculerDistanceMandelbulbAnime(positionEspace + vecteurDecalage.yxy, tempsActuel) +
        vecteurDecalage.xxx * calculerDistanceMandelbulbAnime(positionEspace + vecteurDecalage.xxx, tempsActuel)
    );
}

float calculerOccultationAmbiante(vec3 positionEspace, vec3 normaleSurface, float tempsActuel) {
    float intensiteOccultation = 0.0;
    float facteurEchelle = 1.0;
    for (int etapeEchantillon = 0; etapeEchantillon < 5; etapeEchantillon++) {
        float distanceEchantillon = 0.02 + 0.12 * float(etapeEchantillon) / 4.0;
        float distanceMesuree = calculerDistanceMandelbulbAnime(positionEspace + distanceEchantillon * normaleSurface, tempsActuel);
        intensiteOccultation += (distanceEchantillon - distanceMesuree) * facteurEchelle;
        facteurEchelle *= 0.75;
    }
    return clamp(1.0 - 1.8 * intensiteOccultation, 0.0, 1.0);
}

void mainImage(out vec4 couleurFragment, in vec2 coordonneeFragment) {
    vec2 coordonneesUV = (coordonneeFragment - 0.5 * iResolution.xy) / iResolution.y;

    float tempsActuel = iTime;

    float tempsCycleLocal = mod(tempsActuel, 1.8);
    float secousseCameraImpact = exp(-4.0 * tempsCycleLocal) * sin(tempsCycleLocal * 20.0) * 0.03;

    vec3 positionOrigineRayon = vec3(0.0, 0.0, 2.3 + secousseCameraImpact);
    vec3 directionRayon = normalize(vec3(coordonneesUV, -1.2));

    mat2 matriceRotationY = calculerMatriceRotation2D(tempsActuel * 0.2);
    mat2 matriceRotationX = calculerMatriceRotation2D(0.15 * sin(tempsActuel * 0.3));

    positionOrigineRayon.yz *= matriceRotationX; positionOrigineRayon.xz *= matriceRotationY;
    directionRayon.yz *= matriceRotationX; directionRayon.xz *= matriceRotationY;

    float distanceParcourueTotal = 0.0;
    float distanceParcoursMaximal = 5.0;
    float derniereDistanceStep = 0.0;

    for (int etapeMarchage = 0; etapeMarchage < 160; etapeMarchage++) {
        vec3 positionCouranteRayon = positionOrigineRayon + directionRayon * distanceParcourueTotal;
        float distanceEstimationSurface = calculerDistanceMandelbulbAnime(positionCouranteRayon, tempsActuel);
        if (abs(distanceEstimationSurface) < 0.0004 || distanceParcourueTotal > distanceParcoursMaximal) {
            derniereDistanceStep = distanceEstimationSurface;
            break;
        }
        distanceParcourueTotal += distanceEstimationSurface * 0.2;
    }

    float valeurCouleurArrierePlan = mix(0.02, 0.08, length(coordonneesUV) * 0.7);
    float valeurLuminanceFinale = valeurCouleurArrierePlan;

    if (distanceParcourueTotal < distanceParcoursMaximal) {
        vec3 positionImpactSurface = positionOrigineRayon + directionRayon * distanceParcourueTotal;
        vec3 normaleSurface = calculerNormaleGeometrie(positionImpactSurface, tempsActuel, derniereDistanceStep);
        float facteurOccultationAmbiante = calculerOccultationAmbiante(positionImpactSurface, normaleSurface, tempsActuel);

        vec3 directionLumierePrincipale = normalize(vec3(1.2, 2.0, 1.5));
        vec3 directionLumiereRemplissage = normalize(vec3(-1.5, -1.0, -1.0));

        float composanteDiffusePrincipale = max(dot(normaleSurface, directionLumierePrincipale), 0.0);
        float composanteDiffuseRemplissage = max(dot(normaleSurface, directionLumiereRemplissage), 0.0) * 0.3;

        vec3 directionObservationCamera = -directionRayon;
        vec3 demiVecteurReflexion = normalize(directionLumierePrincipale + directionObservationCamera);

        float composanteSpeculaire = pow(max(dot(normaleSurface, demiVecteurReflexion), 0.0), 32.0);
        float effetFresnel = pow(1.0 - max(dot(directionObservationCamera, normaleSurface), 0.0), 3.0);

        float ombrageBasePattern = 0.4 + 0.3 * cos(length(positionImpactSurface) * 2.5 - tempsActuel * 1.5);

        valeurLuminanceFinale = (ombrageBasePattern * (composanteDiffusePrincipale + composanteDiffuseRemplissage + 0.2) + composanteSpeculaire * 1.4 + effetFresnel * 0.6) * facteurOccultationAmbiante;
        valeurLuminanceFinale = mix(valeurLuminanceFinale, valeurCouleurArrierePlan, 1.0 - exp(-0.4 * distanceParcourueTotal));
    }

    valeurLuminanceFinale = (valeurLuminanceFinale * (2.51 * valeurLuminanceFinale + 0.03)) / (valeurLuminanceFinale * (2.43 * valeurLuminanceFinale + 0.59) + 0.14);
    valeurLuminanceFinale = pow(clamp(valeurLuminanceFinale, 0.0, 1.0), 0.4545);

    couleurFragment = vec4(vec3(valeurLuminanceFinale), 1.0);
}
